/* Slopographic service worker (scope: the site root). See shared/pwa/HANDOFF.md.
 * VERSION is set by node tools/pwa-precache.mjs (a hash of the precached files and this file; the pre-commit hook runs it).
 * A new VERSION is a new cache: the old one is deleted on activate. SlopPWA.refresh() (shared/pwa.js) asks for the version.
 * The PRECACHE list lives in sw-precache.js (generated by: node tools/pwa-precache.mjs) and is loaded with importScripts() below
 * Only same-origin GET requests are handled. Other origins are never cached or intercepted. */
'use strict';

const VERSION = 'v-b367f9c5ca45';
const CACHE = 'slopographic-' + VERSION;
const OFFLINE = '/offline.html';
const STATIC = /\.(m?js|css|woff2?|ttf|otf|png|jpe?g|webp|gif|svg|ico|wasm|json|glb|bcmap|pfb)$/i;

importScripts('/sw-precache.js', '/sw-precache-2.js', '/sw-precache-3.js');

const absolute = (p) => new URL(p, self.location.origin).href;
// A folder navigation ("/drive/") is stored under the file it serves.
const pageKey = (url) => absolute(url.pathname.endsWith('/') ? url.pathname + 'index.html' : url.pathname);
const isNavigation = (req) => req.mode === 'navigate' || (req.headers.get('accept') || '').includes('text/html');
const cacheable = (res) => !!res && res.ok && res.type === 'basic';

// HTML: the network first (so updates show), then the saved copy, then the offline page.
async function networkFirst(req, url) {
  const cache = await caches.open(CACHE);
  try {
    // no-cache: revalidate with the server, so the browser HTTP cache cannot serve an old page.
    const res = await fetch(req, { cache: 'no-cache' });
    if (cacheable(res)) cache.put(pageKey(url), res.clone());
    return res;
  } catch (err) {
    return (await cache.match(pageKey(url))) || (await cache.match(absolute(OFFLINE))) || Response.error();
  }
}

// Static files (scripts, styles, data such as the app registry): the network first, so a new app or a
// changed file shows on the next visit with no reload. The saved copy is used only when offline.
async function networkFirstStatic(req) {
  const cache = await caches.open(CACHE);
  try {
    // no-cache: a changed CSS or script is fetched again on the next visit, never served from the HTTP cache.
    const res = await fetch(req, { cache: 'no-cache' });
    if (cacheable(res)) cache.put(req.url, res.clone());
    return res;
  } catch (err) {
    return (await cache.match(req.url)) || Response.error();
  }
}

self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    // Tolerant: a file that cannot be fetched is reported and skipped; the rest still install.
    const results = await Promise.allSettled(PRECACHE.map(async (p) => {
      const res = await fetch(absolute(p), { cache: 'reload' });
      if (!cacheable(res)) throw new Error(p + ' answered ' + res.status);
      await cache.put(absolute(p), res);
    }));
    results.filter((r) => r.status === 'rejected').forEach((r) => console.warn('[slop sw] precache skipped:', r.reason.message));
    await self.skipWaiting();
  })());
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    for (const name of await caches.keys()) {
      if (name.startsWith('slopographic-') && name !== CACHE) await caches.delete(name);
    }
    await self.clients.claim();
  })());
});

// A page asks which release it is running (Settings shows it): { type: 'version' } is answered on the message's port.
self.addEventListener('message', (event) => {
  if (event.data && event.data.type === 'version' && event.ports[0]) event.ports[0].postMessage({ version: VERSION, cache: CACHE });
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  const url = new URL(req.url);
  if (req.method !== 'GET' || url.origin !== self.location.origin) return;
  if (isNavigation(req)) event.respondWith(networkFirst(req, url));
  else if (STATIC.test(url.pathname)) event.respondWith(networkFirstStatic(req));
});
